        if r > best: best, best_id = r, o
    d['validation']['metrics']['max_abs_library_correlation'] = round(best, 4)
    d['validation']['metrics']['max_corr_library_id'] = best_id
    json.dump(d, open(p, 'w'), indent=2, default=str)
    print('updated', fid, 'max rho = %.4f (%s)' % (best, best_id))
